function renderProperties(){let box=$('#properties');if(!selected){$('#panelTitle').textContent='Propiedades';$('#panelSub').textContent='Personaliza los elementos del modelo';box.innerHTML='<div class="empty-props">Selecciona una entidad o relación en el diagrama para editar sus propiedades.</div>';return}if(selected.type==='entity'){let e=entity(selected.id);if(!e){selected=null;return renderProperties()}$('#panelTitle').textContent=e.name;$('#panelSub').textContent='Entidad · Tabla';box.innerHTML=`<div class="prop-label">Nombre de la entidad</div><input class="input" id="propEntityName" value="${esc(e.name)}"><div class="prop-label">Campos <span style="font-weight:400">(${e.fields.length})</span></div><div class="field-editor">${e.fields.map((f,i)=>`<div class="field-edit"><button class="pk-toggle" title="${f.pk?'Clave primaria':'Marcar como clave primaria'}" data-pk="${i}">${f.pk?'◆':'◇'}</button><input data-fieldname="${i}" value="${esc(f.name)}" aria-label="Nombre del campo"><select data-fieldtype="${i}">${['INT','VARCHAR','TEXT','DATE','DECIMAL','BOOLEAN','UUID'].map(t=>`<option ${f.type===t?'selected':''}>${t}</option>`).join('')}</select><button class="remove" data-remove="${i}" title="Eliminar campo">×</button></div>`).join('')}</div><button class="add-field" id="addField">＋ Añadir campo</button><div class="prop-label" style="margin-top:22px">Acciones</div><button class="btn danger" id="deleteEntity" style="width:100%;justify-content:center">Eliminar entidad</button>`;renderEntityTypeControl(e,box);$('#propEntityName').onchange=ev=>{e.name=ev.target.value||'Sin nombre';persist();render()};box.querySelectorAll('[data-fieldname]').forEach(i=>i.onchange=()=>{e.fields[i.dataset.fieldname].name=i.value||'campo';persist();render()});box.querySelectorAll('[data-fieldtype]').forEach(i=>i.onchange=()=>{e.fields[i.dataset.fieldtype].type=i.value;persist();render()});box.querySelectorAll('[data-pk]').forEach(i=>i.onclick=()=>{e.fields.forEach((f,j)=>f.pk=j===Number(i.dataset.pk));persist();render()});box.querySelectorAll('[data-remove]').forEach(i=>i.onclick=()=>{e.fields.splice(Number(i.dataset.remove),1);persist();render()});$('#addField').onclick=()=>{e.fields.push({name:'nuevo_campo',type:'VARCHAR',pk:false,kind:'simple',children:[]});persist();render()};$('#deleteEntity').onclick=()=>{state.entities=state.entities.filter(x=>x.id!==e.id);state.relations=state.relations.filter(r=>!((r.fromType||'entity')==='entity'&&r.from===e.id)&&!((r.toType||'entity')==='entity'&&r.to===e.id));pruneAggregations();pruneRelations();selected=null;persist();render();toast('Entidad eliminada')}}else if(selected.type==='aggregation'){let g=aggregationById(selected.id);if(!g){selected=null;return renderProperties()}$('#panelTitle').textContent='Agregación';$('#panelSub').textContent=aggregationLabel(g);box.innerHTML='<div class="relation-help">El recuadro agrupa una relación y sus dos entidades. Arrastra el borde para mover el conjunto y úsalo como extremo de otra relación.</div><div class="prop-label">Relación agrupada</div><div class="input" style="height:auto">'+esc(aggregationLabel(g))+'</div><button class="btn danger" id="deleteAggregation" style="width:100%;justify-content:center;margin-top:16px">Quitar agregación</button>';$('#deleteAggregation').onclick=()=>{let id=g.id;state.aggregations=state.aggregations.filter(x=>x.id!==id);state.relations=state.relations.filter(r=>!((r.fromType==='aggregation'&&r.from===id)||(r.toType==='aggregation'&&r.to===id)));pruneRelations();selected=null;persist();render();toast('Agregación eliminada')}}else if(selected.type==='hierarchy'){let h=state.hierarchies.find(x=>x.id===selected.id);if(!h){selected=null;return renderProperties()}renderHierarchyProperties(h,box)}else{let r=state.relations.find(x=>x.id===selected.id);if(!r){selected=null;return renderProperties()}$('#panelTitle').textContent=r.name;$('#panelSub').textContent='Relación · Cardinalidad';box.innerHTML=`<div class="prop-label">Nombre</div><input class="input" id="propRelName" value="${esc(r.name)}"><div class="prop-label">Extremo de origen</div><select class="input" id="propFrom">${opts(r.from,r.fromType,r.id)}</select><div class="prop-label">Extremo de destino</div><select class="input" id="propTo">${opts(r.to,r.toType,r.id)}</select><div class="prop-label">Tipo de relación</div><select class="input" id="propRelationKind"><option value="strong" ${r.kind!=='weak'?'selected':''}>Normal</option><option value="weak" ${r.kind==='weak'?'selected':''}>Débil / identificadora</option></select><div class="prop-label">Cardinalidad principal</div>${cardinalityButtons(ratioFor(r),'property')}<div class="prop-label">Participación por extremo</div><div class="rel-grid"><select class="input" id="propCardFrom">${cardOpts(r.cardFrom)}</select><select class="input" id="propCardTo">${cardOpts(r.cardTo)}</select></div><div class="relation-help">La cardinalidad indica cuántos registros pueden estar vinculados entre ambos extremos.</div><button class="btn danger" id="deleteRelation" style="width:100%;justify-content:center">Eliminar relación</button>`;$('#propRelationKind').onchange=e=>{r.kind=e.target.value;persist();render()};renderParticipationControls(r,box);renderRelationAttributes(r,box);$('#propRelName').onchange=e=>{r.name=e.target.value||'relacion';persist();render()};$('#propFrom').onchange=e=>{let p=parseEndpoint(e.target.value);r.from=p.id;r.fromType=p.type;pruneAggregations();persist();render()};$('#propTo').onchange=e=>{let p=parseEndpoint(e.target.value);r.to=p.id;r.toType=p.type;pruneAggregations();persist();render()};$('#propParticipationFrom').onchange=e=>{r.participationFrom=e.target.value;persist();render()};$('#propParticipationTo').onchange=e=>{r.participationTo=e.target.value;persist();render()};$('#propCardFrom').onchange=e=>{r.cardFrom=e.target.value;persist();render()};$('#propCardTo').onchange=e=>{r.cardTo=e.target.value;persist();render()};box.querySelectorAll('[data-relattr-name]').forEach(i=>i.onchange=()=>{r.attributes[Number(i.dataset.relattrName)].name=i.value||'atributo';persist();render()});box.querySelectorAll('[data-relattr-remove]').forEach(b=>b.onclick=()=>{r.attributes.splice(Number(b.dataset.relattrRemove),1);persist();render()});$('#addRelAttribute').onclick=()=>{r.attributes.push({name:'nuevo_atributo'});persist();render()};$('#deleteRelation').onclick=()=>{state.relations=state.relations.filter(x=>x.id!==r.id);pruneAggregations();pruneRelations();selected=null;persist();render();toast('Relación eliminada')}}}

function openIsaModal(){if(state.entities.length<2){toast('Añade al menos dos entidades para crear una jerarquía');return}let sup=$('#isaSuper'),list=$('#isaSubtypeList');sup.innerHTML=state.entities.map(e=>'<option value="'+e.id+'">'+esc(e.name)+'</option>').join('');list.innerHTML=state.entities.map((e,i)=>'<label class="isa-check"><input type="checkbox" value="'+e.id+'" '+(i===1?'checked':'')+'>'+esc(e.name)+'</label>').join('');sup.onchange=()=>list.querySelectorAll('input').forEach(x=>x.disabled=x.value===sup.value);sup.onchange();$('#isaConstraint').value='disjoint';$('#isaCompleteness').value='partial';$('#isaModal').classList.add('show')}
$('#cancelIsa').onclick=()=>$('#isaModal').classList.remove('show');$('#isaModal').onclick=e=>{if(e.target.id==='isaModal')$('#isaModal').classList.remove('show')};$('#saveIsa').onclick=()=>{let supertype=$('#isaSuper').value,subtypes=Array.from($('#isaSubtypeList').querySelectorAll('input:checked')).map(x=>x.value).filter(id=>id!==supertype);if(!subtypes.length){toast('Selecciona al menos un subtipo distinto del supertipo');return}state.hierarchies.push({id:'h'+uid(),supertype,subtypes,constraint:$('#isaConstraint').value,completeness:$('#isaCompleteness').value,dx:0,dy:0});$('#isaModal').classList.remove('show');persist();render();toast('Jerarquía ISA creada')}
function renderHierarchyProperties(h,box){$('#panelTitle').textContent='Jerarquía ISA';$('#panelSub').textContent=(h.supertypes?.length?h.supertypes:[h.supertype]).map(id=>entity(id)?.name||'Supertipo').join(' + ')+' → '+(h.subtypes||[]).map(id=>entity(id)?.name||'').filter(Boolean).join(', ');box.innerHTML='<div class="prop-label">Tipo del triángulo · restricción</div><select class="input" id="hierConstraint"><option value="disjoint">Excluyente · cada subtipo es único</option><option value="overlap">Solapada · puede pertenecer a varios</option></select><div class="prop-label">Completitud</div><select class="input" id="hierCompleteness"><option value="partial">Parcial</option><option value="total">Total</option></select><div class="relation-help">El arco conecta las ramas de subtipos excluyentes; sin arco, pueden solaparse. El círculo indica especialización total; si no aparece, es parcial.</div><button class="btn danger" id="deleteHierarchy" style="width:100%;justify-content:center">Eliminar jerarquía</button>';$('#hierConstraint').value=h.constraint||'disjoint';$('#hierCompleteness').value=h.completeness||'partial';$('#hierConstraint').onchange=e=>{h.constraint=e.target.value;persist();render()};$('#hierCompleteness').onchange=e=>{h.completeness=e.target.value;persist();render()};$('#deleteHierarchy').onclick=()=>{state.hierarchies=state.hierarchies.filter(x=>x.id!==h.id);selected=null;persist();render();toast('Jerarquía eliminada')}
}
function cardinalityText(v){return v==='1'?'(1,1)':v==='0..1'?'(0,1)':v==='1..N'?'(1,n)':'(0,n)'}
function normalizeState(){if(!Array.isArray(state.entities))state.entities=[];if(!Array.isArray(state.relations))state.relations=[];if(!Array.isArray(state.hierarchies))state.hierarchies=[];if(!Array.isArray(state.aggregations))state.aggregations=[];if(!state.worldCentered){state.entities.forEach(e=>{e.x+=WORLD_X;e.y+=WORLD_Y});state.worldCentered=true;}state.entities.forEach(e=>{if(!e.kind)e.kind='strong';if(!Array.isArray(e.fields))e.fields=[];e.fields.forEach(f=>{if(!f.kind)f.kind='simple';if(!Array.isArray(f.children))f.children=[]})});state.relations.forEach(r=>{if(!Array.isArray(r.attributes))r.attributes=[];if(!r.kind)r.kind='strong';if(!r.participationFrom)r.participationFrom='partial';if(!r.participationTo)r.participationTo='partial'});pruneAggregations();pruneRelations()}function pruneAggregations(){let old=new Set(state.aggregations.map(g=>g.id));state.aggregations=state.aggregations.filter(g=>{let r=state.relations.find(x=>x.id===g.relationId);return r&&(r.fromType||'entity')==='entity'&&(r.toType||'entity')==='entity'&&r.from!==r.to&&entity(r.from)&&entity(r.to)});let keep=new Set(state.aggregations.map(g=>g.id)),gone=new Set([...old].filter(id=>!keep.has(id)));if(gone.size)state.relations=state.relations.filter(r=>!((r.fromType==='aggregation'&&gone.has(r.from))||(r.toType==='aggregation'&&gone.has(r.to))))}function pruneRelations(){let before;do{before=state.relations.length;let relationIds=new Set(state.relations.map(r=>r.id)),aggregationIds=new Set(state.aggregations.map(g=>g.id));state.relations=state.relations.filter(r=>['from','to'].every(side=>{let type=r[side+'Type']||'entity',id=r[side];return type==='relation'?relationIds.has(id)&&id!==r.id:type==='aggregation'?aggregationIds.has(id):!!entity(id)}));state.relations=state.relations.filter(r=>!relationHasCycle(r.id))}while(state.relations.length!==before)}function relationHasCycle(id,trail=new Set(),done=new Set()){if(trail.has(id))return true;if(done.has(id))return false;let r=state.relations.find(x=>x.id===id);if(!r)return false;trail.add(id);for(let side of ['from','to'])if(r[side+'Type']==='relation'&&relationHasCycle(r[side],trail,done))return true;trail.delete(id);done.add(id);return false}
function aggregationById(id){return(state.aggregations||[]).find(g=>g.id===id)}function aggregationLabel(g){let r=state.relations.find(x=>x.id===g.relationId),a=r&&entity(r.from),b=r&&entity(r.to);return r&&a&&b?a.name+' · '+r.name+' · '+b.name:'Agregación'}function aggregationBox(id){let g=typeof id==='object'?id:aggregationById(id),r=g&&state.relations.find(x=>x.id===g.relationId);if(!r||r.fromType==='aggregation'||r.toType==='aggregation'||r.from===r.to)return null;let a=entity(r.from),b=entity(r.to);if(!a||!b)return null;let c=relationCenter(r),pad=28,minX=Math.min(a.x,b.x,c.x-52)-pad,minY=Math.min(a.y,b.y,c.y-28)-pad,maxX=Math.max(a.x+150,b.x+150,c.x+52)+pad,maxY=Math.max(a.y+46,b.y+46,c.y+28)+pad;return{id:g.id,kind:'aggregation',x:minX,y:minY,width:maxX-minX,height:maxY-minY}}function relationEndpoint(r,side){let type=r[side+'Type']||'entity',id=r[side];if(type==='aggregation')return aggregationBox(id);if(type==='relation'){let target=state.relations.find(x=>x.id===id);if(!target||target===r)return null;let c=relationCenter(target);return{id:target.id,kind:'relation',x:c.x-52,y:c.y-28,width:104,height:56}}let e=entity(id);return e?{...e,kind:'entity',width:150,height:46}:null}function relationEndpointLabel(id,type){if(type==='aggregation'){let g=aggregationById(id);return g?'Agregación: '+aggregationLabel(g):'Agregación'}if(type==='relation')return state.relations.find(r=>r.id===id)?.name||'Relación';return entity(id)?.name||'Entidad'}function endpointCenter(e){return{x:e.x+e.width/2,y:e.y+e.height/2}}function relationPairKey(r){let a=(r.fromType||'entity')+':'+r.from,b=(r.toType||'entity')+':'+r.to;return[a,b].sort().join('|')}function relationBase(r){let a=relationEndpoint(r,'from'),b=relationEndpoint(r,'to');if(!a||!b)return{x:0,y:0};let base;if((r.fromType||'entity')==='entity'&&(r.toType||'entity')==='entity'&&r.from===r.to){let e=entity(r.from);base={x:e.x+75,y:e.y-85}}else{let ca=endpointCenter(a),cb=endpointCenter(b);base={x:(ca.x+cb.x)/2,y:(ca.y+cb.y)/2}}let siblings=state.relations.filter(x=>relationPairKey(x)===relationPairKey(r)),index=siblings.findIndex(x=>x.id===r.id);if(siblings.length>1){let ca=endpointCenter(a),cb=endpointCenter(b),fromKey=(r.fromType||'entity')+':'+r.from,toKey=(r.toType||'entity')+':'+r.to;if(fromKey>toKey){let swap=ca;ca=cb;cb=swap}let dx=cb.x-ca.x,dy=cb.y-ca.y,len=Math.hypot(dx,dy);if(len<1){dx=0;dy=-1;len=1}let offset=(index-(siblings.length-1)/2)*84;base.x-=dy/len*offset;base.y+=dx/len*offset}return base}function relationCenter(r){let p=relationBase(r);return{x:p.x+(Number(r.dx)||0),y:p.y+(Number(r.dy)||0)}}function rectangleConnectionPoint(e,targetX,targetY,clearance=4){let w=e.width||150,h=e.height||46,cx=e.x+w/2,cy=e.y+h/2,dx=targetX-cx,dy=targetY-cy;if(Math.abs(dx)+Math.abs(dy)<1)return{x:cx,y:cy};let sx=dx?(w/2+clearance)/Math.abs(dx):Infinity,sy=dy?(h/2+clearance)/Math.abs(dy):Infinity,t=Math.min(sx,sy);return{x:cx+dx*t,y:cy+dy*t}}function entityConnectionPoint(e,targetX,targetY,clearance=4){return rectangleConnectionPoint({...e,width:150,height:46},targetX,targetY,clearance)}function relationConnectionPoint(cx,cy,targetX,targetY,clearance=3){let dx=targetX-cx,dy=targetY-cy,den=Math.abs(dx)/(52+clearance)+Math.abs(dy)/(28+clearance);if(den<1e-9)return{x:cx,y:cy};let t=1/den;return{x:cx+dx*t,y:cy+dy*t}}function endpointConnectionPoint(e,targetX,targetY,clearance=4){if(e.kind==='relation')return relationConnectionPoint(e.x+e.width/2,e.y+e.height/2,targetX,targetY,clearance);return rectangleConnectionPoint(e,targetX,targetY,clearance)}function circleConnectionPoint(cx,cy,targetX,targetY,radius=15,clearance=2){let dx=targetX-cx,dy=targetY-cy,len=Math.hypot(dx,dy)||1,t=(radius+clearance)/len;return{x:cx+dx*t,y:cy+dy*t}}
function hierarchyBase(h){let superIds=h.supertypes?.length?h.supertypes:[h.supertype],sups=superIds.map(entity).filter(Boolean),subs=(h.subtypes||[]).map(entity).filter(Boolean);if(!sups.length||!subs.length)return{x:0,y:0};let avgSupX=sups.reduce((n,e)=>n+e.x+75,0)/sups.length,avgSubX=subs.reduce((n,e)=>n+e.x+75,0)/subs.length,maxBottom=Math.max(...sups.map(e=>e.y+46)),minY=Math.min(...subs.map(e=>e.y));return{x:(avgSupX+avgSubX)/2,y:maxBottom<minY?(maxBottom+minY)/2:maxBottom+84}}function hierarchyCenter(h){let p=hierarchyBase(h);return{x:p.x+(Number(h.dx)||0),y:p.y+(Number(h.dy)||0)}}function relationAttributePosition(r,f,i,n){let c=relationCenter(r),ang=-Math.PI/2+2*Math.PI*i/n,rad=105;return{x:c.x+(Number.isFinite(f.dx)?f.dx:Math.cos(ang)*rad),y:c.y+(Number.isFinite(f.dy)?f.dy:Math.sin(ang)*rad)}}
function renderEntityTypeControl(e,box){let h=Array.from(box.querySelectorAll('.prop-label')).find(x=>x.textContent.includes('Campos'));if(!h)return;let wrap=document.createElement('div');wrap.innerHTML='<div class=\"prop-label\">Tipo de entidad</div><select class=\"input\" id=\"entityKind\"><option value=\"strong\">Entidad fuerte</option><option value=\"weak\">Entidad débil</option></select>';let select=wrap.querySelector('select');select.value=e.kind||'strong';select.onchange=()=>{e.kind=select.value;persist();render()};h.before(...wrap.childNodes)}
function renderParticipationControls(r,box){let help=box.querySelector('.relation-help');if(!help)return;let wrap=document.createElement('div');wrap.innerHTML='<div class=\"prop-label\">Participación</div><div class=\"rel-grid\"><label class=\"part-label\">Origen<select class=\"input\" id=\"propParticipationFrom\"><option value=\"partial\">Parcial</option><option value=\"total\">Total</option></select></label><label class=\"part-label\">Destino<select class=\"input\" id=\"propParticipationTo\"><option value=\"partial\">Parcial</option><option value=\"total\">Total</option></select></label></div>';wrap.querySelector('#propParticipationFrom').value=r.participationFrom||'partial';wrap.querySelector('#propParticipationTo').value=r.participationTo||'partial';help.before(...wrap.childNodes)}
function renderRelationAttributes(r,box){let help=box.querySelector('.relation-help');if(!help)return;if(!Array.isArray(r.attributes))r.attributes=[];let wrap=document.createElement('div');wrap.innerHTML='<div class=\"prop-label\">Atributos descriptivos de la relación</div><div class=\"rel-attribute-list\"></div><button type=\"button\" class=\"add-field\" id=\"addRelAttribute\">＋ Añadir atributo</button>';let list=wrap.querySelector('.rel-attribute-list');r.attributes.forEach((a,i)=>{let row=document.createElement('div');row.className='relation-attribute-row';let input=document.createElement('input');input.className='input';input.value=a.name||'';input.setAttribute('data-relattr-name',i);input.setAttribute('aria-label','Atributo de relación');let remove=document.createElement('button');remove.className='remove';remove.type='button';remove.textContent='×';remove.title='Eliminar atributo';remove.dataset.relattrRemove=i;row.append(input,remove);list.appendChild(row)});help.before(...wrap.childNodes)}
function ratioFor(r){let a=String(r.cardFrom||'1').includes('N')?'N':'1',b=String(r.cardTo||'0..N').includes('N')?'N':'1';return a==='N'&&b==='N'?'N:M':a+':'+b}function setCardinality(r,v){if(v==='1:1'){r.cardFrom='1';r.cardTo='1'}else if(v==='N:M'){r.cardFrom='0..N';r.cardTo='0..N'}else{r.cardFrom='1';r.cardTo='0..N'}}function cardinalityButtons(value,scope){return '<div class="cardinality-choices" data-scope="'+scope+'">'+[['1:1','Uno a uno'],['1:N','Uno a muchos'],['N:M','Muchos a muchos']].map(([v,label])=>'<button type="button" class="cardinality-option'+(v===value?' active':'')+'" data-cardinality="'+v+'" data-scope="'+scope+'"><b>'+v+'</b><small>'+label+'</small></button>').join('')+'</div>'}function relationDependsOn(id,target,seen=new Set()){if(id===target)return true;if(seen.has(id))return false;seen.add(id);let r=state.relations.find(x=>x.id===id);return!!r&&['from','to'].some(side=>r[side+'Type']==='relation'&&relationDependsOn(r[side],target,seen))}function relationEndpointOptions(value,ownerId=null){let entities=state.entities.map(e=>{let v='entity:'+e.id;return'<option value="'+v+'" '+(value===v?'selected':'')+'>'+esc(e.name)+'</option>'}).join(''),groups=(state.aggregations||[]).map(g=>{let v='aggregation:'+g.id;return'<option value="'+v+'" '+(value===v?'selected':'')+'>Agregación: '+esc(aggregationLabel(g))+'</option>'}).join(''),relations=state.relations.filter(r=>!ownerId||(r.id!==ownerId&&!relationDependsOn(r.id,ownerId))).map(r=>{let v='relation:'+r.id;return'<option value="'+v+'" '+(value===v?'selected':'')+'>Relación: '+esc(r.name)+'</option>'}).join('');return entities+groups+relations}function parseEndpoint(value){let i=value.indexOf(':');return i<0?{type:'entity',id:value}:{type:value.slice(0,i),id:value.slice(i+1)}}function endpointValue(r,side){return(r[side+'Type']||'entity')+':'+r[side]}function opts(id,type='entity',ownerId=null){return relationEndpointOptions((type||'entity')+':'+id,ownerId)}function cardOpts(v){return ['1','0..1','1..N','0..N'].map(x=>`<option ${x===v?'selected':''}>${x}</option>`).join('')}
