   if(!r||!id(r.from)||!id(r.to))throw Error('Relación inválida');
   const copy={id:unique(r.id),name:text(r.name,'relaciona'),from:r.from,to:r.to,fromType:['entity','relation','aggregation'].includes(r.fromType)?r.fromType:'entity',toType:['entity','relation','aggregation'].includes(r.toType)?r.toType:'entity',cardFrom:['1','0..1','1..N','0..N'].includes(r.cardFrom)?r.cardFrom:'1',cardTo:['1','0..1','1..N','0..N'].includes(r.cardTo)?r.cardTo:'0..N',participationFrom:r.participationFrom==='total'?'total':'partial',participationTo:r.participationTo==='total'?'total':'partial',kind:r.kind==='weak'?'weak':'strong',attributes:[]};
