   if(!candidate||!Array.isArray(candidate.entities)||!Array.isArray(candidate.relations))throw Error('No es un proyecto Forma');
   if(data.version!==2)candidate=stateFromExport(data);
   candidate=validateImportedState(candidate);
   if(!confirm('¿Abrir el archivo? Se reemplazará el modelo de este navegador. Puedes exportarlo antes como JSON.'))return;
   state=candidate;selected=null;$('#projectName').value=typeof data.project==='string'?data.project.slice(0,100):'Modelo importado';
